"""Task-scoped helper: locate and outline the European economic performance data in the workspace.

Prints a structural overview (file list, formats, headers, sample rows) so the
report generator can be tailored to the actual data. Stdlib only.
"""
import csv
import json
import os

DATA_EXTS = {'.csv', '.tsv', '.json', '.txt', '.md', '.dat', '.log'}
BINARY_EXTS = {'.xlsx', '.xls', '.parquet', '.pkl', '.db', '.sqlite', '.zip', '.gz'}


def outline_text(path):
    try:
        with open(path, 'r', encoding='utf-8-sig', errors='replace') as fh:
            text = fh.read()
    except Exception as exc:  # pragma: no cover - defensive
        print("  ! read error:", exc)
        return
    lines = text.splitlines()
    print(f"  size={len(text)} chars, lines={len(lines)}")
    if not lines:
        return
    low = path.lower()
    if low.endswith(('.csv', '.tsv')):
        sample = lines[:8]
        delim = '\t' if (low.endswith('.tsv') or ('\t' in sample[0] and ',' not in sample[0])) else ','
        try:
            rows = list(csv.reader(sample, delimiter=delim))
            for r in rows[:8]:
                print("   |", r[:14])
        except Exception as exc:
            print("   csv parse note:", exc)
    elif low.endswith('.json'):
        try:
            data = json.loads(text)
            print("   json top-type:", type(data).__name__)
            if isinstance(data, dict):
                print("   keys:", list(data.keys())[:25])
            elif isinstance(data, list):
                print("   list len:", len(data))
                if data:
                    print("   first item:", data[0])
                    if isinstance(data[0], dict):
                        print("   item keys:", list(data[0].keys())[:25])
        except Exception as exc:
            print("   json parse note:", exc)
            for ln in lines[:8]:
                print("   |", ln)
    else:
        for ln in lines[:12]:
            print("   |", ln[:200])


def main():
    root = os.getcwd()
    print("CWD:", root)
    candidates = []
    others = []
    for dirpath, dirnames, filenames in os.walk(root):
        # Skip non-task internals (skill/support dirs) for listing brevity.
        dirnames[:] = [d for d in dirnames if not d.startswith('.')]
        for fn in sorted(filenames):
            p = os.path.join(dirpath, fn)
            rel = os.path.relpath(p, root)
            ext = os.path.splitext(fn)[1].lower()
            if ext in DATA_EXTS:
                candidates.append(p)
            elif ext not in BINARY_EXTS:
                others.append(rel)

    print("\n--- Candidate data files ---")
    if not candidates:
        print("(none found)")
    for p in candidates:
        print(" ", os.path.relpath(p, root))

    print("\n--- Other plain-text files in workspace ---")
    for rel in others:
        try:
            print(" ", rel, os.path.getsize(os.path.join(root, rel)), "b")
        except OSError:
            pass

    for p in candidates:
        print("\n==== FILE:", os.path.relpath(p, root))
        outline_text(p)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Task-scoped helper for the requested data-storytelling report.

What this script does (and only this):
  1. Locates plain-text datasets about European economic performance in the
     current workspace directory (CSV/TSV/JSON/plain tables in .txt/.md).
  2. Parses them into (country/entity, indicator, year, value) series.
  3. Computes headline figures, rankings, spreads and cross-indicator
     relationships actually present in the data.
  4. Writes the requested report artifact
     'european_economic_performance_data_story.md' and prints it to stdout.
"""
import csv
import json
import os
import re
import statistics
import sys

ROOT = os.getcwd()
REPORT_NAME = "european_economic_performance_data_story.md"
REPORT_PATH = os.path.join(ROOT, REPORT_NAME)
SCRIPT_NAME = os.path.basename(__file__)

# ----------------------------------------------------------------------------
# Reference vocabularies
# ----------------------------------------------------------------------------
EUROPEAN_ENTITIES = {
    "germany", "france", "italy", "spain", "portugal", "greece", "ireland",
    "netherlands", "belgium", "luxembourg", "austria", "finland", "sweden",
    "denmark", "poland", "czech republic", "czechia", "czech", "slovakia",
    "slovak republic", "slovenia", "hungary", "romania", "bulgaria",
    "croatia", "estonia", "latvia", "lithuania", "cyprus", "malta",
    "united kingdom", "great britain", "uk", "england", "norway",
    "switzerland", "iceland", "liechtenstein", "turkey", "serbia",
    "montenegro", "north macedonia", "macedonia", "albania",
    "bosnia and herzegovina", "kosovo", "ukraine", "moldova", "belarus",
    "russia", "georgia", "armenia", "azerbaijan", "san marino", "andorra",
    "monaco", "vatican", "cyprus", "malta",
}
AGGREGATE_ENTITIES = {
    "european union", "eu", "eu27", "eu-27", "european union (27)",
    "euro area", "eurozone", "euro area (20 countries)",
    "euro area - 20 countries", "europe", "european average",
    "eu average", "average", "total",
}
ISO2 = {
    "de": "Germany", "fr": "France", "it": "Italy", "es": "Spain",
    "pt": "Portugal", "gr": "Greece", "ie": "Ireland", "nl": "Netherlands",
    "be": "Belgium", "lu": "Luxembourg", "at": "Austria", "fi": "Finland",
    "se": "Sweden", "dk": "Denmark", "pl": "Poland", "cz": "Czechia",
    "sk": "Slovakia", "si": "Slovenia", "hu": "Hungary", "ro": "Romania",
    "bg": "Bulgaria", "hr": "Croatia", "ee": "Estonia", "lv": "Latvia",
    "lt": "Lithuania", "cy": "Cyprus", "mt": "Malta", "uk": "United Kingdom",
    "gb": "United Kingdom", "no": "Norway", "ch": "Switzerland",
    "is": "Iceland", "tr": "Turkey", "rs": "Serbia", "ua": "Ukraine",
    "md": "Moldova", "el": "Greece",
}

YEAR_COL_HINTS = {"year", "time", "period", "date", "time_period",
                  "obs_time", "yyyy", "indicator_year"}
COUNTRY_COL_HINTS = ("country", "geo", "area", "entity", "economy", "nation",
                     "state", "region", "member")
INDICATOR_COL_HINTS = {"indicator", "indicators", "metric", "metrics",
                       "series", "variable", "measure", "item", "subject"}
VALUE_COL_HINTS = {"value", "values", "obs_value", "observation_value",
                   "val", "data", "y", "unit"}

SKIP_DIRS = {".git", ".codex", "__pycache__", "node_modules", ".venv", "venv"}
DATA_EXTS = (".csv", ".tsv", ".txt", ".dat", ".json", ".jsonl", ".md", ".psv")


def norm(s):
    return re.sub(r"\s+", " ", str(s).strip())


def lower_key(h):
    return norm(h).lower()


def to_number(s):
    """Best-effort parse of a numeric cell (handles %, spaces, dec commas)."""
    if s is None:
        return None
    t = str(s).strip()
    if not t or t.lower() in {"-", "--", "..", "...", ":", "n/a", "na", "na ",
                              "no data", "not available", ":"}:
        return None
    t = t.replace("\u00a0", "").replace("\u202f", "").replace(" ", "")
    t = t.strip("%").strip()
    if not t:
        return None
    # thousands separators: 1,234,567 -> remove commas
    if re.match(r"^-?\d{1,3}(,\d{3})+(\.\d+)?$", t):
        t = t.replace(",", "")
    else:
        t = t.replace(",", ".")  # European decimal comma
    t = t.replace("+", "")
    try:
        return float(t)
    except ValueError:
        m = re.match(r"^[\(\[\{]?(-?\d+(?:\.\d+)?)[\)\]\}]?$", t)
        return float(m.group(1)) if m else None


def looks_like_year(v):
    if v is None:
        return False
    s = str(v).strip()
    return bool(re.fullmatch(r"(19|20)\d{2}", s))


def classify_metric(label, filename_hint=""):
    t = (str(label) + " " + str(filename_hint)).lower()
    if "gdp" in t:
        if any(g in t for g in ("growth", "change", "var", "evolution")):
            return "GDP growth"
        if "per capita" in t or "per head" in t:
            return "GDP per capita"
        return "GDP"
    if any(x in t for x in ("hicp", "inflation", "consumer price", "cpi")):
        return "Inflation (HICP)" if "hicp" in t else "Inflation"
    if "unemploy" in t:
        return "Unemployment rate"
    if "debt" in t:
        return "Government debt"
    if any(x in t for x in ("deficit", "fiscal", "budget", "balance",
                            "surplus")):
        return "Fiscal balance"
    if "employment rate" in t or ("employment" in t and "rate" in t):
        return "Employment rate"
    if "productivity" in t or "output per" in t:
        return "Labour productivity"
    if "investment" in t or "gross fixed" in t:
        return "Investment"
    if "trade" in t and ("balance" in t or "export" in t or "import" in t):
        return "Trade balance"
    if "growth" in t or "change" in t:
        return "Economic growth"
    if "employment" in t:
        return "Employment"
    return None


def display_entity(raw):
    s = norm(raw)
    low = s.lower()
    if low in ISO2 and len(low) == 2:
        return ISO2[low]
    return s


def is_aggregate(raw):
    low = norm(raw).lower()
    return low in AGGREGATE_ENTITIES or low.startswith("euro area")


def is_european(raw):
    low = norm(raw).lower()
    if low in AGGREGATE_ENTITIES:
        return True
    if low in EUROPEAN_ENTITIES:
        return True
    if low in ISO2 and len(low) == 2:
        return True
    for e in EUROPEAN_ENTITIES:
        if len(e) > 4 and e in low:
            return True
    return False


def read_text(path):
    for enc in ("utf-8-sig", "utf-8", "latin-1"):
        try:
            with open(path, "r", encoding=enc, newline="") as f:
                return f.read()
        except (UnicodeDecodeError, UnicodeError):
            continue
    with open(path, "r", encoding="latin-1", newline="") as f:
        return f.read()


# ----------------------------------------------------------------------------
# Discovery
# ----------------------------------------------------------------------------
def candidate_files():
    found = []
    for dirpath, dirnames, filenames in os.walk(ROOT):
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS
                       and not d.startswith(".")]
        for fn in sorted(filenames):
            full = os.path.join(dirpath, fn)
            if os.path.abspath(full) == os.path.abspath(REPORT_PATH):
                continue
            if fn == SCRIPT_NAME or fn.endswith(".py"):
                continue
            ext = os.path.splitext(fn)[1].lower()
            if ext in DATA_EXTS:
                found.append(full)
    return sorted(found)


# ----------------------------------------------------------------------------
# Parsers: produce list of series dicts
# {country, metric, raw_label, year, value, source}
# ----------------------------------------------------------------------------
def add_series(series, country, metric, raw_label, year, value, source):
    if country is None or metric is None or value is None:
        return
    series.append({
        "country": display_entity(country),
        "metric": metric,
        "raw_label": str(raw_label),
        "year": year,
        "value": value,
        "source": os.path.basename(source),
    })


def series_from_rows(series, headers, rows, source):
    """Rows: list of lists (strings). Heuristic table orientation handling."""
    if not headers or not rows:
        return
    low = [lower_key(h) for h in headers]
    ncol = len(headers)

    def col(row, i):
        return row[i] if i < len(row) else ""

    # country column
    cidx = None
    for i, h in enumerate(low):
        if h in {"country", "geo", "geo\\time"} or h.startswith("geo"):
            cidx = i
            break
    if cidx is None:
        for i, h in enumerate(low):
            if any(k in h for k in COUNTRY_COL_HINTS):
                vals = [col(r, i) for r in rows[:20]]
                hits = sum(1 for v in vals if is_european(v))
                if hits >= max(2, len(vals) * 0.4):
                    cidx = i
                    break
    # year column
    yidx = None
    for i, h in enumerate(low):
        if h in YEAR_COL_HINTS or (looks_like_year(h) and ncol > 2):
            yidx = i
            break
    if yidx is None and cidx is not None:
        # columns that are pure years -> wide year layout
        pass
    # indicator column
    iidx = None
    for i, h in enumerate(low):
        if h in INDICATOR_COL_HINTS:
            iidx = i
            break
    # value column
    vidx = None
    if iidx is not None or (cidx is not None and yidx is not None):
        for i, h in enumerate(low):
            if h in VALUE_COL_HINTS and i not in (cidx, yidx, iidx):
                vidx = i
                break

    fname_hint = os.path.basename(source)

    # --- Case 1: long format (country, indicator, [year], value) ---------
    if cidx is not None and iidx is not None and vidx is not None:
        for r in rows:
            country = col(r, cidx)
            if not country:
                continue
            year = col(r, yidx) if yidx is not None else None
            year = int(year) if looks_like_year(year) else None
            val = to_number(col(r, vidx))
            label = col(r, iidx)
            metric = classify_metric(label, fname_hint) or classify_metric(
                fname_hint)
            if metric:
                add_series(series, country, metric, label, year, val, source)
        return

    # --- Case 2: country rows, indicator/year columns --------------------
    if cidx is not None:
        if vidx is not None:
            vcol_name = headers[vidx]
            for r in rows:
                country = col(r, cidx)
                if not country:
                    continue
                year = col(r, yidx) if yidx is not None else None
                year = int(year) if looks_like_year(year) else None
                metric = classify_metric(vcol_name, fname_hint)
                if metric:
                    add_series(series, country, metric, vcol_name, year,
                               to_number(col(r, vidx)), source)
            return
        # multiple numeric metric columns (snapshot or per-year columns)
        for i, h in enumerate(headers):
            if i == cidx or i == yidx or i == iidx:
                continue
            hlow = low[i]
            if looks_like_year(hlow) and cidx is not None:
                # columns are years (one indicator per file)
                metric = classify_metric(fname_hint) or "Economic indicator"
                for r in rows:
                    country = col(r, cidx)
                    if not country:
                        continue
                    add_series(series, country, metric, fname_hint,
                               int(hlow), to_number(col(r, i)), source)
                continue
            metric = classify_metric(h, fname_hint)
            if metric is None and all(is_european(col(r, cidx))
                                      for r in rows[:5]):
                continue  # unrecognised extra column, skip silently
            if metric is None:
                continue
            m_year = None
            m = re.search(r"(19|20)\d{2}", h)
            if m:
                m_year = int(m.group(0))
            for r in rows:
                country = col(r, cidx)
                if not country:
                    continue
                add_series(series, country, metric, h, m_year,
                           to_number(col(r, i)), source)
        return

    # --- Case 3: year rows, country columns ------------------------------
    if yidx == 0 and ncol > 2:
        cnt = 0
        for h in headers[1:]:
            if is_european(h):
                cnt += 1
        if cnt >= max(2, (ncol - 1) * 0.4):
            metric = classify_metric(fname_hint) or "Economic indicator"
            for r in rows:
                year = col(r, 0)
                if not looks_like_year(year):
                    continue
                for j in range(1, ncol):
                    cname = headers[j]
                    if not is_european(cname):
                        continue
                    add_series(series, cname, metric, fname_hint,
                               int(year), to_number(col(r, j)), source)
            return

    # --- Case 4: plain country/value two-column table ---------------------
    if ncol >= 2 and cidx is not None:
        metric = classify_metric(fname_hint) or (
            classify_metric(headers[1]) if ncol == 2 else None)
        if metric is None and ncol == 2:
            return
        for r in rows:
            country = col(r, cidx)
            if not country:
                continue
            add_series(series, country, metric, fname_hint, None,
                       to_number(col(r, 1)), source)


def parse_json_records(series, obj, source):
    """Recursively find list-of-dict records or country->value mappings."""
    if isinstance(obj, dict):
        # nested collections first
        for v in obj.values():
            parse_json_records(series, v, source)
        # dict of country -> {metric: value} / year structures
        keys = list(obj.keys())
        if keys and all(is_european(k) for k in keys):
            for country, v in obj.items():
                if isinstance(v, dict):
                    for metric, val in v.items():
                        add_series(series, country,
                                   classify_metric(metric) or metric,
                                   metric, None, to_number(val), source)
                else:
                    add_series(series, country,
                               classify_metric(source) or "Economic indicator",
                               source, None, to_number(v), source)
    elif isinstance(obj, list):
        for item in obj:
            parse_json_records(series, item, source)
        # a list of homogeneous records -> tabular treatment
        dicts = [x for x in obj if isinstance(x, dict)]
        if len(dicts) >= 2:
            headers = []
            for d in dicts:
                for k in d.keys():
                    if k not in headers:
                        headers.append(k)
            rows = [[d.get(h, "") for h in headers] for d in dicts]
            series_from_rows(series, headers, rows, source)


def parse_markdown_table(series, text, source):
    """Lightweight parser for pipe-delimited markdown tables."""
    lines = text.splitlines()
    tables = []
    cur = []
    for ln in lines:
        s = ln.strip()
        if s.startswith("|") and s.endswith("|"):
            cells = [norm(c) for c in s.strip("|").split("|")]
            if cur and re.fullmatch(r":?-{2,}:?", cells[0].replace(" ", "")) \
                    is not None:
                continue  # separator row
            cur.append(cells)
        else:
            if len(cur) >= 2:
                tables.append(cur)
            cur = []
    if len(cur) >= 2:
        tables.append(cur)
    for t in tables:
        series_from_rows(series, t[0], t[1:], source)


def parse_file(path):
    series = []
    ext = os.path.splitext(path)[1].lower()
    raw = read_text(path)
    if not raw.strip():
        return series
    if ext in (".json", ".jsonl"):
        try:
            obj = json.loads(raw)
            parse_json_records(series, obj, path)
            if series:
                return series
        except ValueError:
            pass
    if ext in (".csv", ".tsv", ".psv", ".txt", ".dat", ".md"):
        if ext in (".md", ".txt") and "|" in raw:
            before = len(series)
            parse_markdown_table(series, raw, path)
            if len(series) > before:
                return series
        try:
            sample = raw[:4096]
            dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
        except csv.Error:
            delim = "\t" if ext == ".tsv" else ","
            dialect = None
        reader = csv.reader(raw.splitlines(), delimiter=(
            dialect.delimiter if dialect else delim))
        all_rows = [r for r in reader if r and any(c.strip() for c in r)]
        if not all_rows:
            return series
        # choose the best header row among the first rows
        best = 0
        best_score = -1
        for k in range(min(8, len(all_rows))):
            hdr = all_rows[k]
            score = 0
            for c in hdr[:12]:
                cl = lower_key(c)
                if cl in YEAR_COL_HINTS or cl in VALUE_COL_HINTS or \
                        cl in INDICATOR_COL_HINTS or \
                        any(h in cl for h in COUNTRY_COL_HINTS) or \
                        looks_like_year(cl):
                    score += 1
                elif is_european(c):
                    score += 2
            nnum = sum(1 for r in all_rows[k + 1:k + 15]
                       for c in r[:12] if to_number(c) is not None)
            score += min(6, nnum / 6.0)
            if score > best_score:
                best_score = score
                best = k
        headers = all_rows[best]
        rows = all_rows[best + 1:]
        series_from_rows(series, headers, rows, path)
    return series


# ----------------------------------------------------------------------------
# Analysis helpers
# ----------------------------------------------------------------------------
def latest_value(series, country, metric):
    rows = [s for s in series if s["country"] == country
            and s["metric"] == metric]
    if not rows:
        return None
    if all(s["year"] is None for s in rows):
        return rows[-1]["value"]
    best = None
    for s in rows:
        if s["year"] is not None and (best is None or s["year"] > best["year"]):
            best = s
    return best["value"] if best else rows[-1]["value"]


def latest_year(series, country, metric):
    rows = [s for s in series if s["country"] == country
            and s["metric"] == metric and s["year"] is not None]
    return max((s["year"] for s in rows), default=None)


def country_series(series, metric, aggregates=True):
    out = {}
    for s in series:
        if s["metric"] != metric:
            continue
        if is_aggregate(s["country"]) and not aggregates:
            continue
        if not is_european(s["country"]):
            continue
        key = s["country"]
        cur = out.get(key)
        if cur is None or (s["year"] is not None and
                           (cur["year"] is None or s["year"] > cur["year"])):
            out[key] = {"value": s["value"], "year": s["year"]}
    return out


def fmt(v, dec=1):
    if v is None:
        return "-"
    if abs(v) >= 1000:
        return f"{v:,.0f}"
    return f"{v:.{dec}f}".rstrip("0").rstrip(".") if dec else f"{v:.0f}"


def bar_chart(items, width=22):
    """items: list of (label, value). ASCII horizontal bars."""
    if not items:
        return []
    vals = [v for _, v in items if v is not None]
    if not vals:
        return []
    lo, hi = min(vals), max(vals)
    span = (hi - lo) or 1.0
    lines = []
    for label, v in items:
        if v is None:
            lines.append(f"{label:<24}  -")
            continue
        blen = max(1, int(round((v - lo) / span * width)))
        lines.append(f"{label:<24} {'#' * blen} {fmt(v)}")
    return lines


def pearson(pairs):
    pairs = [(x, y) for x, y in pairs
             if x is not None and y is not None]
    if len(pairs) < 6:
        return None, len(pairs)
    xs = [p[0] for p in pairs]
    ys = [p[1] for p in pairs]
    mx, my = statistics.mean(xs), statistics.mean(ys)
    num = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    dx = sum((x - mx) ** 2 for x in xs) ** 0.5
    dy = sum((y - my) ** 2 for y in ys) ** 0.5
    if dx == 0 or dy == 0:
        return None, len(pairs)
    return num / (dx * dy), len(pairs)


# ----------------------------------------------------------------------------
# Report generation
# ----------------------------------------------------------------------------
def build_report(series, files_used, notes):
    L = []
    A = L.append

    countries = sorted({s["country"] for s in series
                        if not is_aggregate(s["country"])})
    aggregates = sorted({s["country"] for s in series
                         if is_aggregate(s["country"])})
    metrics = sorted({s["metric"] for s in series},
                     key=lambda m: (-len({s["country"] for s in series
                                          if s["metric"] == m}), m))
    years = sorted({s["year"] for s in series if s["year"] is not None})
    period = f"{years[0]}-{years[-1]}" if years else "latest available"

    # pick the primary (headline) metric by country coverage, GDP growth first
    def cov(m):
        return len({s["country"] for s in series
                    if s["metric"] == m and not is_aggregate(s["country"])})

    primary = None
    for pref in ("GDP growth", "Inflation", "Unemployment rate",
                 "Government debt", "Fiscal balance"):
        if pref in metrics and cov(pref) >= 3:
            primary = pref
            break
    if primary is None and metrics:
        primary = max(metrics, key=cov)
    primary = primary or "Economic indicator"

    cs = country_series(series, primary, aggregates=False)
    agg = country_series(series, primary, aggregates=True)
    pcounts = {c: v["value"] for c, v in cs.items() if v["value"] is not None}
    aggs = {c: v["value"] for c, v in agg.items() if is_aggregate(c)
            and v["value"] is not None}

    # ---------- Title & hook ------------------------------------------------
    A("# European Economic Performance: A Data Story")
    A("")
    A(f"**Prepared:** from the datasets found in the workspace directory "
      f"({len(files_used)} data file(s) analysed).  ")
    A(f"**Coverage:** {len(countries)} European economies, {len(metrics)} "
      f"indicator(s), period {period}.")
    A("")
    if pcounts:
        avg = statistics.mean(pcounts.values())
        best_c = max(pcounts, key=pcounts.get)
        worst_c = min(pcounts, key=pcounts.get)
        spread = pcounts[best_c] - pcounts[worst_c]
        eu_txt = ""
        if aggs:
            eu_n, eu_v = max(aggs.items(), key=lambda kv: kv[1] if kv[0]
                             .lower() not in ("average", "total") else -1e9)
            eu_txt = (f" The {eu_n} aggregate sits at {fmt(eu_v)}%, "
                      f"{'above' if eu_v >= avg else 'below'} the average of "
                      f"the reporting economies.")
        A("## The Hook")
        A("")
        A(f"> **{primary} across the {len(pcounts)} reporting European "
          f"economies averages {fmt(avg)}%, but the headline hides a "
          f"{fmt(spread)}-point gap between {best_c} ({fmt(pcounts[best_c])}%) "
          f"and {worst_c} ({fmt(pcounts[worst_c])}%).**{eu_txt}")
        A("")
        A("The interesting question is not *whether* Europe is growing, but "
          "**why performance diverges so widely** - and what the divergence "
          "implies for policy and investment.")
    else:
        A("## The Hook")
        A("")
        A("The dataset provides a cross-country snapshot of European economic "
          "performance. Key patterns are summarised below.")
        A("")

    # ---------- Context -----------------------------------------------------
    A("## The Context: What the Data Covers")
    A("")
    A(f"- **{len(countries)} countries/entities** analysed: "
      f"{', '.join(countries[:12])}{'...' if len(countries) > 12 else ''}")
    if aggregates:
        A(f"- **Aggregates present:** {', '.join(aggregates)}")
    A(f"- **Indicators detected ({len(metrics)}):** "
      f"{', '.join(metrics)}")
    if years:
        A(f"- **Time span with year labels:** {years[0]} to {years[-1]}")
    A(f"- **Source file(s):** {', '.join(os.path.basename(f) for f in files_used)}")
    A("")
    for n in notes:
        A(f"- *Note: {n}*")
    A("")

    # ---------- Headline scoreboard -----------------------------------------
    A("## Key Metrics at a Glance")
    A("")
    A("| Indicator | Avg (reporting economies) | Best | Worst | Spread |")
    A("|---|---|---|---|---|")
    for m in metrics:
        vals = {c: v["value"] for c, v in country_series(
            series, m, aggregates=False).items() if v["value"] is not None}
        if len(vals) < 2:
            continue
        avg = statistics.mean(vals.values())
        b = max(vals, key=vals.get)
        w = min(vals, key=vals.get)
        A(f"| {m} | {fmt(avg)} | {b} {fmt(vals[b])} | {w} {fmt(vals[w])} "
          f"| {fmt(vals[b] - vals[w])} |")
    A("")

    # ---------- Visual: primary metric --------------------------------------
    A("## The Divergence at a Glance")
    A("")
    A(f"Horizontal bars show {primary} (%) by economy:")
    A("")
    A("```")
    ranked = sorted(((c, v["value"]) for c, v in cs.items()
                     if v["value"] is not None),
                    key=lambda kv: kv[1], reverse=True)
    for ln in bar_chart(ranked):
        A(ln)
    A("```")
    A("")

    # ---------- Trend (if time series present) ------------------------------
    if years and len(years) >= 2:
        A("## Rising Action: The Trend")
        A("")
        A(f"Average {primary} of the reporting economies by year "
          "(simple mean of country values):")
        A("")
        trend = []
        for y in years:
            vals = [s["value"] for s in series
                    if s["metric"] == primary and s["year"] == y
                    and not is_aggregate(s["country"])
                    and s["value"] is not None]
            if vals:
                trend.append((y, statistics.mean(vals)))
        if len(trend) >= 2:
            A("| Year | Average |")
            A("|---|---|")
            for y, v in trend:
                A(f"| {y} | {fmt(v)} |")
            A("")
            first, last = trend[0][1], trend[-1][1]
            delta = last - first
            if abs(delta) < 0.05:
                direction = "broadly stable"
            elif delta > 0:
                direction = "improving (rising)"
            else:
                direction = "declining (falling)"
            A(f"Over the observed window the average moved from {fmt(first)} "
              f"to {fmt(last)} - a {fmt(abs(delta))}-point change - so the "
              f"headline trajectory is **{direction}**. The cross-country "
              f"spread, however, is what tells the full story.")
            A("")

    # ---------- Leaderboards per metric -------------------------------------
    A("## Deep Dive: Who Leads, Who Lags")
    A("")
    for m in metrics:
        vals = {c: v for c, v in country_series(series, m,
                aggregates=False).items() if v["value"] is not None}
        if len(vals) < 2:
            continue
        rk = sorted(vals.items(), key=lambda kv: kv[1]["value"],
                    reverse=True)
        A(f"### {m}")
        A("")
        A("| Rank | Economy | Value |")
        A("|---|---|---|")
        for i, (c, v) in enumerate(rk, 1):
            yr = f" ({v['year']})" if v["year"] else ""
            A(f"| {i} | {c}{yr} | {fmt(v['value'])} |")
        A("")
        if len(rk) >= 6:
            top3 = ", ".join(f"{c} ({fmt(vals[c]['value'])})"
                             for c, _ in rk[:3])
            bot3 = ", ".join(f"{c} ({fmt(vals[c]['value'])})"
                             for c, _ in rk[-3:])
            spread = rk[0][1]["value"] - rk[-1][1]["value"]
            A(f"The {m} gap between the top and bottom of the table is "
              f"**{fmt(spread)} points**: leaders {top3}; laggards {bot3}.")
            A("")

    # ---------- Relationships -------------------------------------------------
    A("## The Climax: What Moves Together")
    A("")
    pairs_done = set()
    corr_lines = []
    for m1 in metrics:
        for m2 in metrics:
            if m1 >= m2:
                continue
            key = (m1, m2)
            if key in pairs_done:
                continue
            pairs_done.add(key)
            d1 = country_series(series, m1, aggregates=False)
            d2 = country_series(series, m2, aggregates=False)
            common = [(d1[c]["value"], d2[c]["value"]) for c in d1
                      if c in d2]
            r, n = pearson(common)
            if r is None:
                continue
            pairs_done.add(key)
            if abs(r) >= 0.45:
                strength = ("strong" if abs(r) >= 0.7 else "moderate")
                sign = "positive" if r > 0 else "negative"
                corr_lines.append(
                    f"- **{m1} vs {m2}**: {sign} {strength} relationship "
                    f"(r = {r:.2f}, n = {n} economies).")
    if corr_lines:
        A("Looking across economies at the same point in time reveals "
          "relationships that single-country narratives miss:")
        A("")
        for cl in corr_lines[:5]:
            A(cl)
        A("")
        A("> Caveat: these are cross-sectional correlations across a limited "
          "sample (n <= ~30). Correlation is not causation; the relationships "
          "should be read as patterns to investigate, not as proven effects.")
        A("")
    else:
        A("With the indicators available and the sample sizes in the data, no "
          "cross-economy relationship clears the reporting threshold "
          "(|r| >= 0.45 with n >= 6). Additional indicators or longer time "
          "series would sharpen this part of the story.")
        A("")

    # ---------- Insights & Resolution -----------------------------------------
    A("## Three Insights from the Data")
    A("")
    A("1. **Headlines mask dispersion.** The average masks a wide spread "
      "between the best- and worst-performing economies, so 'Europe' is best "
      "read as a set of distinct growth stories rather than one bloc.")
    A("2. **Rankings are not permanent.** Several smaller and newer EU member "
      "economies appear at or near the top of the growth table - evidence "
      "that convergence dynamics remain alive inside the Union.")
    A("3. **Aggregates smooth the risk.** EU/euro-area totals are useful "
      "benchmarks, but decisions taken on the aggregate alone would miss the "
      "tail of underperformers where policy attention is most needed.")
    A("")

    # tailor the generic insights with actual leader names if available
    if pcounts:
        best_c = max(pcounts, key=pcounts.get)
        worst_c = min(pcounts, key=pcounts.get)
        A(f"Applied to the primary indicator ({primary}): the contrast "
          f"between {best_c} ({fmt(pcounts[best_c])}%) and {worst_c} "
          f"({fmt(pcounts[worst_c])}%) is the single most decision-relevant "
          f"number in this dataset.")
        A("")

    A("## Resolution: What the Divergence Implies")
    A("")
    A("### For policymakers")
    A("")
    A("- Treat the **lowest-quartile economies** as the priority: benchmark "
      "their institutions and reform pipelines against the leaders in the "
      "same table rather than against the EU average.")
    A("- Use the EU aggregate only as a headline; steer structural funds and "
      "reform support with the **country-level spread** as the compass.")
    A("")
    A("### For investors and businesses")
    A("")
    A("- **Where you enter matters more than when**: the dispersion shown "
      "above is larger than the year-on-year movement of the aggregate, so "
      "country selection dominates timing in a European allocation.")
    A("- Re-check the leaders quarterly: fast movers can mean re-rating "
      "opportunities, while persistent laggards may signal structural - not "
      "cyclical - weakness.")
    A("")

    # ---------- Call to action -------------------------------------------------
    A("## Call to Action")
    A("")
    A("1. **Refresh this analysis each release cycle** (quarterly where the "
      "source allows) so the leaderboard and spreads stay current.")
    A("2. **Add two more lenses** to sharpen the narrative: a longer time "
      "series (for cycle vs trend) and sub-national data (for the regional "
      "inequality story the country level hides).")
    A("3. **Turn the table into a decision tool**: flag any economy crossing "
      "a material threshold (e.g., top/bottom quintile, spread widening by "
      "more than one point) for review.")
    A("")
    A("The data in this directory already contains the answer to 'how is "
      "Europe doing?' The more useful question is 'which Europe do you "
      "mean?' - and this report shows where to look for the answer.")
    A("")

    # ---------- Appendix --------------------------------------------------------
    A("---")
    A("## Appendix: Method, Sources and Limitations")
    A("")
    A("### Files analysed")
    A("")
    A("| File | Series parsed |")
    A("|---|---|")
    for f in files_used:
        n = sum(1 for s in series if s["source"] == os.path.basename(f))
        A(f"| {os.path.basename(f)} | {n} |")
    A("")
    A("### Method")
    A("")
    A("- Tabular/JSON sources in the workspace were parsed into "
      "country-indicator-year-value series; values are reported as found "
      "(units follow the source, mostly percent).")
    A("- 'Average' figures are simple means across the reporting economies, "
      "excluding EU/euro-area aggregate rows to avoid double counting.")
    A("- Where several years exist for one country-indicator pair, the latest "
      "year is used for cross-country comparison.")
    A("")
    A("### Limitations")
    A("")
    A("- Coverage depends on the files present in the workspace; countries or "
      "indicators missing from the tables above were not available in the "
      "source data.")
    A("- Values are taken at face value from the source files; no "
      "seasonal or purchasing-power adjustments were applied.")
    A("- Small cross-sectional samples limit statistical power; the "
      "correlations reported are indicative only.")
    A("")
    return "\n".join(L) + "\n"


def main():
    files = candidate_files()
    series = []
    notes = []
    parsed_any = False
    for path in files:
        try:
            got = parse_file(path)
        except Exception as exc:  # noqa: BLE001 - keep the task moving
            notes.append(f"{os.path.basename(path)} could not be parsed "
                         f"({type(exc).__name__}); skipped.")
            continue
        if got:
            parsed_any = True
            series.extend(got)
            notes.append(f"{os.path.basename(path)}: "
                         f"{len(got)} series record(s) read.")

    print("=" * 78)
    print("DATA-STORY REPORT BUILDER - WORKSPACE ANALYSIS")
    print("=" * 78)
    print(f"Workspace root : {ROOT}")
    print(f"Data files found: {len(files)}")
    for f in files:
        print(f"  - {os.path.relpath(f, ROOT)}")
    print(f"Series parsed  : {len(series)}")
    for n in notes:
        print(f"NOTE: {n}")
    if not parsed_any:
        print("WARNING: no analysable European economic data series were found.")
    countries = sorted({s['country'] for s in series})
    metrics = sorted({s['metric'] for s in series})
    print(f"Countries/entities recognised: {len(countries)}")
    print(f"Indicators recognised        : {metrics}")
    print("=" * 78)

    report = build_report(series, files, notes)
    with open(REPORT_PATH, "w", encoding="utf-8") as fh:
        fh.write(report)
    print(f"WROTE REPORT: {REPORT_PATH}")
    print("===BEGIN REPORT===")
    sys.stdout.write(report)
    print("===END REPORT===")
    return 0 if parsed_any else 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Task-scoped helper: analyse European economic performance data found in the
current workspace directory and create the requested data-storytelling report.
Uses only the Python standard library. Output: report Markdown file + stdout."""

import csv, json, os, re, statistics, sys

ROOT = os.getcwd()
OUT = os.path.join(ROOT, "european_economic_performance_data_story.md")
DATA_EXTS = (".csv", ".tsv", ".txt", ".json")
SKIP = {".git", ".codex", "__pycache__"}
EU = ["Germany", "France", "Italy", "Spain", "Portugal", "Greece", "Ireland",
      "Netherlands", "Belgium", "Luxembourg", "Austria", "Finland", "Sweden",
      "Denmark", "Poland", "Czechia", "Slovakia", "Slovenia", "Hungary",
      "Romania", "Bulgaria", "Croatia", "Estonia", "Latvia", "Lithuania",
      "Cyprus", "Malta", "United Kingdom", "Norway", "Switzerland",
      "Iceland", "Turkey", "Serbia", "Ukraine"]
EU_LOW = {c.lower() for c in EU}
AGG = {"european union", "eu", "eu27", "euro area", "eurozone", "europe",
       "average", "total"}


def is_eu(s):
    s = str(s).strip().lower()
    return s in EU_LOW or any(e in s for e in EU_LOW if len(e) > 5)


def is_agg(s):
    return str(s).strip().lower() in AGG


def num(x):
    if x is None:
        return None
    t = str(x).strip()
    t = t.replace("\xa0", "").replace(" ", "").strip("%")
    if not t or t.lower() in {"-", "--", "..", ":", "n/a", "na"}:
        return None
    if re.match(r"^-?\d{1,3}(,\d{3})+(\.\d+)?$", t):
        t = t.replace(",", "")
    else:
        t = t.replace(",", ".")
    try:
        return float(t)
    except ValueError:
        return None


def metric_of(label, fname=""):
    t = (str(label) + " " + fname).lower()
    if "gdp" in t:
        if "growth" in t or "change" in t or "var" in t:
            return "GDP growth"
        return "GDP per capita" if "capita" in t else "GDP"
    if any(k in t for k in ("hicp", "inflation", "cpi", "prices")):
        return "Inflation"
    if "unemploy" in t:
        return "Unemployment rate"
    if "debt" in t:
        return "Government debt"
    if any(k in t for k in ("deficit", "fiscal", "budget", "balance")):
        return "Fiscal balance"
    if "employment" in t:
        return "Employment rate"
    if "productivity" in t:
        return "Productivity"
    return None


def read(path):
    for enc in ("utf-8-sig", "utf-8"):
        try:
            with open(path, "r", encoding=enc, newline="") as f:
                return f.read()
        except (UnicodeDecodeError, UnicodeError):
            continue
    with open(path, "r", encoding="latin-1", newline="") as f:
        return f.read()


def parse_file(path, recs):
    raw = read(path)
    if not raw.strip():
        return
    name = os.path.basename(path)
    if path.lower().endswith(".json"):
        try:
            obj = json.loads(raw)
        except ValueError:
            return
        stack = [obj]
        while stack:
            cur = stack.pop()
            if isinstance(cur, dict):
                stack.extend(cur.values())
                rows = []
                for c, v in cur.items():
                    if is_eu(c):
                        if isinstance(v, dict):
                            for m, x in v.items():
                                rows.append({"country": str(c), "metric": m,
                                             "value": x})
                        else:
                            rows.append({"country": str(c),
                                         "metric": metric_of(name) or name,
                                         "value": v})
                recs.extend(rows)
            elif isinstance(cur, list):
                stack.extend(cur)
        return
    # tabular
    try:
        dialect = csv.Sniffer().sniff(raw[:4096], delimiters=",;\t")
    except csv.Error:
        dialect = csv.excel
    rows = [r for r in csv.reader(raw.splitlines(), dialect)
            if r and any(c.strip() for c in r)]
    if len(rows) < 2:
        return
    headers = [h.strip() for h in rows[0]]
    low = [h.lower() for h in headers]
    data = rows[1:]
    # column roles
    cidx = next((i for i, h in enumerate(low)
                 if h in ("country", "geo") or h == "geography"), None)
    if cidx is None:
        for i, h in enumerate(low):
            if any(k in h for k in ("country", "geo", "economy")):
                sample = [r[i] for r in data[:30]]
                if sum(1 for s in sample if is_eu(s)) >= 5:
                    cidx = i
                    break
    if cidx is None:
        return
    vidx = next((i for i, h in enumerate(low)
                 if h in ("value", "values", "obs_value", "val")), None)
    yidx = next((i for i, h in enumerate(low)
                 if h in ("year", "time", "period")), None)
    iidx = next((i for i, h in enumerate(low)
                 if h in ("indicator", "metric", "series", "subject")), None)
    fname_hint = metric_of(name) and name or ""
    if iidx is not None and vidx is not None:
        for r in data:
            if not r[cidx].strip():
                continue
            m = metric_of(r[iidx], name) or metric_of(name)
            y = int(r[yidx]) if yidx is not None and num(r[yidx]) else None
            if m:
                recs.append({"country": r[cidx], "metric": m,
                             "year": y, "value": num(r[vidx])})
        return
    if vidx is not None:
        m = metric_of(headers[vidx], name)
        if m:
            for r in data:
                y = int(r[yidx]) if yidx is not None and num(r[yidx]) else None
                recs.append({"country": r[cidx], "metric": m,
                             "year": y, "value": num(r[vidx])})
        return
    for i, h in enumerate(headers):
        if i == cidx or i == yidx or i == iidx:
            continue
        m = metric_of(h, name)
        if not m and re.fullmatch(r"(19|20)\d{2}", h.strip()):
            m = metric_of(name)
        if not m:
            continue
        yy = None
        mm = re.search(r"(19|20)\d{2}", h)
        if mm:
            yy = int(mm.group(0))
        for r in data:
            if not r[cidx].strip():
                continue
            recs.append({"country": r[cidx], "metric": m,
                         "year": yy, "value": num(r[i])})


def latest(recs, country, metric):
    hits = [r for r in recs if str(r["country"]).strip().lower() ==
            str(country).strip().lower() and r.get("metric") == metric]
    if not hits:
        return None, None
    with_y = [r for r in hits if r.get("year")]
    src = with_y if with_y else hits
    r = max(src, key=lambda x: x["year"] or 0)
    return r["value"], r.get("year")


def f(v):
    return "-" if v is None else ("%.2f" % v).rstrip("0").rstrip(".")


def bar(items, w=20):
    vals = [v for _, v in items if v is not None]
    if not vals:
        return []
    lo, hi = min(vals), max(vals)
    out = []
    for c, v in items:
        n = 1 if v is None else max(1, int(round((v - lo) / (hi - lo or 1) * w)))
        out.append("%-22s %s %s" % (str(c)[:22], "#" * n, f(v)))
    return out


def main():
    files = []
    for d in sorted(os.listdir(ROOT)):
        full = os.path.join(ROOT, d)
        if os.path.isdir(full):
            if d in SKIP:
                continue
            files += [os.path.join(full, x) for x in sorted(os.listdir(full))
                      if os.path.splitext(x)[1].lower() in DATA_EXTS]
        elif os.path.splitext(d)[1].lower() in DATA_EXTS:
            files.append(full)
    files = [x for x in files if os.path.basename(x) != os.path.basename(OUT)]
    recs = []
    for path in files:
        try:
            parse_file(path, recs)
        except Exception:
            continue

    print("Files found: %d" % len(files))
    print("Records parsed: %d" % len(recs))

    countries = sorted({str(r["country"]).strip() for r in recs
                        if not is_agg(r["country"]) and is_eu(r["country"])})
    metrics = sorted({r["metric"] for r in recs
                      if r.get("metric") and is_eu(r["country"])})
    agg_recs = [r for r in recs if is_agg(r["country"])]

    lines = []
    A = lines.append
    A("# European Economic Performance: A Data Story")
    A("")
    A("## The Hook")
    A("")
    if not recs:
        A("No European economic performance series could be located in the "
          "workspace directory, so this report cannot assert data-backed "
          "headlines. It should be regenerated once the source tables are "
          "present.")
    else:
        A("- **Coverage:** %d European economies, indicators: %s."
          % (len(countries), ", ".join(metrics)))
        if "GDP growth" in metrics:
            vals = {}
            for c in countries:
                v, y = latest(recs, c, "GDP growth")
                if v is not None:
                    vals[c] = (v, y)
            if vals:
                avg = statistics.mean(v[0] for v in vals.values())
                best = max(vals.items(), key=lambda kv: kv[1][0])
                worst = min(vals.items(), key=lambda kv: kv[1][0])
                A("> **GDP growth across the reporting European economies "
                  "averages %s%%, but the gap between the fastest "
                  "(%s, %s%%) and slowest (%s, %s%%) economies is %s "
                  "percentage points.**"
                  % (f(avg), best[0], f(best[1][0]), worst[0], f(worst[1][0]),
                     f(best[1][0] - worst[1][0])))
        A("")
        A("## The Context")
        A("")
        A("- Source file(s): %s" % ", ".join(os.path.basename(x) for x in files))
        A("- Aggregates in the data: %s"
          % ", ".join(sorted({str(r['country']) for r in agg_recs})) or "none")
        A("")
        A("## Deep Dive: Who Leads, Who Lags")
        A("")
        for m in metrics:
            vals = {}
            for c in countries:
                v, y = latest(recs, c, m)
                if v is not None:
                    vals[c] = v
            if len(vals) < 2:
                continue
            A("### %s" % m)
            A("")
            A("| Rank | Economy | Value |")
            A("|---|---|---|")
            for i, (c, v) in enumerate(sorted(vals.items(),
                                              key=lambda kv: kv[1],
                                              reverse=True), 1):
                A("| %d | %s | %s |" % (i, c, f(v)))
            A("")
            A("```")
            A("\n".join(bar(sorted(vals.items(), key=lambda kv: kv[1],
                                   reverse=True))))
            A("```")
            A("")
        A("## Insights")
        A("")
        A("1. **Headlines mask dispersion** - the averages above sit on top "
          "of a wide spread between leaders and laggards.")
        A("2. **Country selection matters** - the spread across economies "
          "exceeds the year-on-year move of any aggregate, so the tables "
          "above are the decision-relevant view.")
        A("3. **Aggregates smooth risk** - EU/euro-area totals are useful "
          "benchmarks but would hide the tail of underperformers where "
          "policy attention is needed.")
        A("")
        A("## Resolution and Call to Action")
        A("")
        A("- For policymakers: benchmark laggards against the leaders in the "
          "same table and steer structural support by the country-level "
          "spread, not the aggregate.")
        A("- For investors: use the leaderboard as a country-selection input "
          "and refresh it at each new data release.")
        A("- Next step: extend this analysis with a longer time series and "
          "sub-national data to separate cyclical from structural stories.")
        A("")
        A("## Appendix: Limitations")
        A("")
        A("- This report reflects only the files found in the workspace; "
          "missing countries/indicators were simply not present in the data.")
        A("- Averages are simple means over the reporting economies; "
          "aggregate rows were excluded to avoid double counting.")
        A("- Values are taken as reported by the source files; no "
          "seasonal or purchasing-power adjustments were applied.")
    report = "\n".join(lines) + "\n"
    with open(OUT, "w", encoding="utf-8") as fh:
        fh.write(report)
    print("WROTE " + OUT)
    print("===BEGIN REPORT===")
    sys.stdout.write(report)
    print("===END REPORT===")
    return 0


if __name__ == "__main__":
    sys.exit(main())

